const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const coastalRegion = ee.Geometry.Polygon([
    [[140.0, -39.0], [155.0, -39.0], [155.0, -28.0], [140.0, -28.0], [140.0, -39.0]]
  ]);

  const date1 = '2019-07-24';
  const date2 = '2020-01-01';

  // 2. Data Acquisition - MCD19A2 for Aerosol Optical Depth (smoke proxy)
  const modisAOD = ee.ImageCollection('MODIS/061/MCD19A2_GRANULES')
    .filterBounds(coastalRegion)
    .select('Optical_Depth_047');

  const img1 = modisAOD.filterDate(date1, ee.Date(date1).advance(1, 'day')).first();
  const img2 = modisAOD.filterDate(date2, ee.Date(date2).advance(1, 'day')).first();

  // Check if images exist
  const img1Exists = img1 ? true : false;
  const img2Exists = img2 ? true : false;

  if (!img1Exists || !img2Exists) {
    console.log(`2019-07-24 Image: ${img1Exists ? 'Yes' : 'No'}`);
    console.log(`2020-01-01 Image: ${img2Exists ? 'Yes' : 'No'}`);
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Calculate mean AOD values
  const reducer = ee.Reducer.mean().combine({
    reducer2: ee.Reducer.count(),
    sharedInputs: true
  });

  const stats1 = img1.reduceRegion({
    reducer: reducer,
    geometry: coastalRegion,
    scale: 1000,
    maxPixels: 1e9
  });

  const stats2 = img2.reduceRegion({
    reducer: reducer,
    geometry: coastalRegion,
    scale: 1000,
    maxPixels: 1e9
  });

  const mean1 = stats1.get('Optical_Depth_047_mean');
  const count1 = stats1.get('Optical_Depth_047_count');
  const mean2 = stats2.get('Optical_Depth_047_mean');
  const count2 = stats2.get('Optical_Depth_047_count');

  // Get values
  const mean1Val = mean1.getInfo();
  const count1Val = count1.getInfo();
  const mean2Val = mean2.getInfo();
  const count2Val = count2.getInfo();

  console.log(`2019-07-24: AOD=${mean1Val?.toFixed(3)}, Pixels=${count1Val}`);
  console.log(`2020-01-01: AOD=${mean2Val?.toFixed(3)}, Pixels=${count2Val}`);

  // 4. Validation & Final Answer
  if (count1Val === 0 || count2Val === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  if (mean1Val === null || mean2Val === null || 
      isNaN(mean1Val) || isNaN(mean2Val) ||
      mean1Val < 0 || mean2Val < 0 || mean1Val > 5 || mean2Val > 5) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Compare AOD values (higher AOD = more smoke)
  if (mean2Val > mean1Val) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
